<template><div class="plan-layer" @mousedown.self="close"><section class="plan-modal" role="dialog" aria-modal="true"><header><div class="plan-title"><span :class="type"><i :class="type==='medication'?'ph ph-pill':'ph ph-clipboard-text'"></i></span><div><small>NUEVO PLAN CLÍNICO</small><h2>Plan de {{ type === 'medication' ? 'medicamentos' : 'procedimientos' }}</h2><p>{{ patientName }} · Orden de trabajo #{{ context.workOrderId }}</p></div></div><button class="btn-close" :disabled="saving" @click="close"></button></header>
<div class="modal-body"><div v-if="activePlan" class="active-warning"><i class="ph ph-warning"></i><div><strong>Ya existe un plan activo #{{ activePlan.id }}</strong><p>Para crear uno nuevo deberá confirmar la suspensión del plan actual.</p></div></div><div class="row g-3 mb-4"><div v-if="type==='medication'" class="col-md-6"><label class="form-label">Inicio general</label><input v-model="generalStart" type="datetime-local" class="form-control"></div><div :class="type==='medication'?'col-md-6':'col-12'"><label class="form-label">Observaciones generales</label><textarea v-model.trim="observations" class="form-control" rows="2" maxlength="1000"></textarea></div></div>
<div class="d-flex justify-content-between align-items-center mb-2"><div><h3 class="h6 mb-0">{{ type==='medication'?'Medicamentos':'Servicios' }} del plan</h3><small class="text-muted">Agregue al menos un elemento completo.</small></div><button class="btn btn-outline-primary btn-sm" :disabled="saving" @click="add"><i class="ph ph-plus me-1"></i>Agregar</button></div>
<div class="plan-items"><article v-for="(item,index) in items" :key="item.key" class="plan-item"><div class="item-number">{{ index+1 }}</div><button v-if="items.length>1" class="remove-item" :disabled="saving" aria-label="Eliminar fila" @click="items.splice(index,1)"><i class="ph ph-trash"></i></button>
<template v-if="type==='medication'"><div class="row g-3"><div class="col-md-7"><label class="form-label">Medicamento *</label><input v-model.trim="item.search" class="form-control form-control-sm mb-1" placeholder="Buscar por nombre"><select v-model="item.id_medicamento" class="form-select" :class="invalid(index,'id_medicamento')"><option value="">Seleccione</option><option v-for="option in medicationOptions(item.search)" :key="option.id" :value="option.id">{{ name(option) }}</option></select><div class="invalid-feedback">{{ error(index,'id_medicamento') }}</div></div><div class="col-md-5"><label class="form-label">Vía *</label><select v-model="item.id_viaadministracion" class="form-select" :class="invalid(index,'id_viaadministracion')"><option value="">Seleccione</option><option v-for="option in store.vias" :key="option.id" :value="option.id">{{ name(option) }}</option></select></div><div class="col-md-4"><label class="form-label">Dosis *</label><input v-model.trim="item.dosis" class="form-control" placeholder="Ej. 500 mg" :class="invalid(index,'dosis')"></div><div class="col-md-4"><label class="form-label">Cada *</label><div class="input-group"><input v-model.number="item.frecuencia_valor" type="number" min="1" class="form-control"><select v-model="item.frecuencia_id" class="form-select"><option value="">Unidad</option><option v-for="option in store.frecuencias" :key="option.id" :value="option.id">{{ name(option) }}</option></select></div></div><div class="col-md-4"><label class="form-label">Durante *</label><div class="input-group"><input v-model.number="item.duracion_valor" type="number" min="1" class="form-control"><select v-model="item.duracion_id" class="form-select"><option value="">Unidad</option><option v-for="option in store.frecuencias" :key="option.id" :value="option.id">{{ name(option) }}</option></select></div></div><div class="col-md-5"><label class="form-label">Inicio particular</label><input v-model="item.hora_inicio" type="datetime-local" class="form-control"></div><div class="col-md-7"><label class="form-label">Indicaciones</label><input v-model.trim="item.observaciones" class="form-control" maxlength="500"></div></div></template>
<template v-else><div class="row g-3"><div class="col-md-7"><label class="form-label">Servicio *</label><input v-model.trim="item.search" class="form-control form-control-sm mb-1" placeholder="Buscar servicio"><select v-model="item.id_servicio" class="form-select" :class="invalid(index,'id_servicio')"><option value="">Seleccione</option><option v-for="option in serviceOptions(item.search)" :key="option.id" :value="option.id">{{ name(option) }}</option></select><div class="invalid-feedback">{{ error(index,'id_servicio') }}</div></div><div class="col-md-2"><label class="form-label">Cantidad *</label><input v-model.number="item.cantidad" type="number" min="1" max="100" class="form-control"></div><div class="col-md-3"><label class="form-label">Prioridad</label><select v-model="item.prioridad" class="form-select"><option v-for="p in priorities" :key="p" :value="p">{{ p }}</option></select></div><div class="col-md-5"><label class="form-label">Fecha programada</label><input v-model="item.fecha_hora_programada" type="datetime-local" class="form-control"></div><div class="col-md-7"><label class="form-label">Indicaciones</label><input v-model.trim="item.indicaciones" class="form-control" maxlength="1000"></div></div></template></article></div><div v-if="formError" class="alert alert-danger mt-3">{{ formError }}</div></div>
<footer><div class="plan-summary"><strong>{{ items.length }}</strong><span>{{ type==='medication'?(items.length===1?'medicamento':'medicamentos'):(items.length===1?'servicio':'servicios') }}</span></div><div><button class="btn btn-outline-secondary me-2" :disabled="saving" @click="close">Cancelar</button><button class="btn btn-primary" :disabled="saving" @click="review"><span v-if="saving" class="spinner-border spinner-border-sm me-2"></span>{{ saving?'Creando plan…':'Revisar y crear plan' }}</button></div></footer></section>
<div v-if="confirming" class="confirm-layer"><section class="confirm-card"><span class="confirm-icon"><i class="ph ph-checklist"></i></span><h2>Confirmar plan clínico</h2><p v-if="type==='medication'">Se creará un plan con <strong>{{ items.length }} medicamentos</strong> para {{ patientName }}.</p><p v-else>Se creará un plan con <strong>{{ items.length }} servicios</strong> y <strong>{{ totalActivities }} actividades</strong> en total.</p><div v-if="activePlan" class="alert alert-warning"><strong>El plan activo #{{ activePlan.id }} será suspendido.</strong> Sus elementos pendientes dejarán de pertenecer al plan vigente.</div><div class="d-flex justify-content-end gap-2"><button class="btn btn-outline-secondary" @click="confirming=false">Volver y revisar</button><button class="btn btn-primary" @click="save">{{ activePlan?'Suspender y crear nuevo':'Confirmar creación' }}</button></div></section></div></div></template>
<script setup>import{computed,reactive,ref}from'vue';import{obtenerMensajeError}from'@/services/api';import{usePatientPlansStore}from'@/store/pinia/planesPaciente';const props=defineProps({type:{type:String,required:true},context:{type:Object,required:true},patientName:String,activePlan:Object});const emit=defineEmits(['close','saved']);const store=usePatientPlansStore(),saving=computed(()=>props.type==='medication'?store.savingMedicationPlan:store.savingProcedurePlan),observations=ref(''),confirming=ref(false),formError=ref(''),fieldErrors=ref({}),priorities=['baja','media','alta','urgente'];const now=()=>{const d=new Date(),o=d.getTimezoneOffset();return new Date(d.getTime()-o*60000).toISOString().slice(0,16)};const generalStart=ref(now()),items=reactive([]);const name=i=>i.nombre||i.name||i.descripcion||`#${i.id}`;const medRow=()=>({key:crypto.randomUUID(),search:'',id_medicamento:'',id_viaadministracion:'',dosis:'',frecuencia_id:'',frecuencia_valor:1,duracion_id:'',duracion_valor:1,hora_inicio:'',observaciones:''});const procRow=()=>({key:crypto.randomUUID(),search:'',id_servicio:'',cantidad:1,prioridad:'media',fecha_hora_programada:'',indicaciones:''});const add=()=>items.push(props.type==='medication'?medRow():procRow());add();const filter=(list,q)=>list.filter(i=>name(i).toLowerCase().includes(String(q).toLowerCase())).slice(0,60);const medicationOptions=q=>filter(store.medicamentos,q),serviceOptions=q=>filter(store.servicios,q);const error=(i,k)=>fieldErrors.value[`${props.type==='medication'?'medicamentos':'servicios'}.${i}.${k}`]?.[0]||'';const invalid=(i,k)=>error(i,k)?'is-invalid':'';const apiDate=v=>v?v.replace('T',' ')+':00':null;const totalActivities=computed(()=>items.reduce((s,i)=>s+Number(i.cantidad||0),0));function close(){if(!saving.value)emit('close')}function validate(){if(!items.length)return'Agregue al menos un elemento.';if(props.type==='medication'&&items.some(i=>!i.id_medicamento||!i.id_viaadministracion||!i.dosis||!i.frecuencia_id||i.frecuencia_valor<1||!i.duracion_id||i.duracion_valor<1))return'Complete todos los campos obligatorios de cada medicamento.';if(props.type==='procedure'&&items.some(i=>!i.id_servicio||i.cantidad<1||i.cantidad>100))return'Complete el servicio y una cantidad válida entre 1 y 100.';if(props.type==='procedure'&&new Set(items.map(i=>String(i.id_servicio))).size!==items.length)return'No puede repetir un servicio dentro del mismo plan.';return''}function review(){formError.value=validate();if(!formError.value)confirming.value=true}async function save(){confirming.value=false;formError.value='';fieldErrors.value={};try{const base={id_paciente:props.context.patientId,id_orden_trabajo:props.context.workOrderId,observaciones:observations.value,...(props.activePlan?{force:true}:{})};let result;if(props.type==='medication'){result=await store.saveMedication({...base,hora_inicio:apiDate(generalStart.value),medicamentos:items.map(({key,search,...i})=>({...i,id_medicamento:Number(i.id_medicamento),id_viaadministracion:Number(i.id_viaadministracion),frecuencia_id:Number(i.frecuencia_id),duracion_id:Number(i.duracion_id),hora_inicio:apiDate(i.hora_inicio)||apiDate(generalStart.value)}))})}else{result=await store.saveProcedure({...base,servicios:items.map(({key,search,...i})=>({...i,id_servicio:Number(i.id_servicio),cantidad:Number(i.cantidad),fecha_hora_programada:apiDate(i.fecha_hora_programada),id_profesional_asignado:null}))})}emit('saved',result)}catch(e){fieldErrors.value=e.payload?.errors||{};formError.value=obtenerMensajeError(e)}}</script>
<style scoped>.plan-layer{position:fixed;inset:0;z-index:1080;display:grid;place-items:center;padding:1rem;background:rgba(6,19,33,.65);backdrop-filter:blur(5px);overflow:auto}.plan-modal{width:min(1000px,100%);max-height:95vh;overflow:auto;background:#fff;border-radius:1rem;box-shadow:0 30px 90px rgba(0,0,0,.3)}.plan-modal>header,.plan-modal>footer{position:sticky;z-index:3;display:flex;justify-content:space-between;align-items:center;padding:1rem 1.3rem;background:#fff;border-bottom:1px solid #e7ecf1}.plan-modal>header{top:0}.plan-modal>footer{bottom:0;border-top:1px solid #e7ecf1;border-bottom:0}.plan-title{display:flex;gap:.8rem}.plan-title>span{display:grid;place-items:center;width:45px;height:45px;border-radius:13px;font-size:1.25rem}.plan-title>span.medication{background:#e8f3fc;color:#237eb9}.plan-title>span.procedure{background:#e8f8f0;color:#248e64}.plan-title small{color:var(--bs-primary);font-size:.6rem;font-weight:800}.plan-title h2{font-size:1.1rem;margin:.1rem 0}.plan-title p{margin:0;color:#768598;font-size:.7rem}.modal-body{padding:1.3rem}.active-warning{display:flex;gap:.7rem;padding:.8rem;margin-bottom:1rem;border-radius:.7rem;background:#fff5df;color:#8b6416}.active-warning p{margin:0;font-size:.72rem}.plan-items{display:grid;gap:.8rem}.plan-item{position:relative;padding:1rem 1rem 1rem 2.8rem;border:1px solid #e1e8ee;border-radius:.8rem;background:#fbfcfd}.item-number{position:absolute;left:.8rem;top:1rem;display:grid;place-items:center;width:25px;height:25px;border-radius:8px;background:#e7f2fb;color:var(--bs-primary);font-size:.7rem;font-weight:800}.remove-item{position:absolute;z-index:1;right:.6rem;top:.5rem;border:0;background:transparent;color:#bd4450}.plan-summary{display:flex;align-items:center;gap:.4rem}.plan-summary strong{font-size:1.3rem;color:var(--bs-primary)}.plan-summary span{font-size:.72rem;color:#768598}.confirm-layer{position:fixed;inset:0;z-index:1090;display:grid;place-items:center;padding:1rem;background:rgba(5,16,29,.7)}.confirm-card{width:min(510px,100%);padding:1.5rem;background:#fff;border-radius:1rem;box-shadow:0 25px 70px rgba(0,0,0,.3)}.confirm-card h2{font-size:1.2rem}.confirm-icon{display:grid;place-items:center;width:52px;height:52px;margin-bottom:1rem;border-radius:14px;background:#eaf5fc;color:var(--bs-primary);font-size:1.4rem}@media(max-width:575px){.plan-modal>footer{align-items:stretch;flex-direction:column;gap:.7rem}.plan-modal>footer>div:last-child{display:grid;gap:.4rem}.plan-modal>footer .btn{margin:0!important}.plan-item{padding-left:1rem;padding-top:2.7rem}}</style>
